<template><ManagementShell><section class="grid gap-4"><header><p class="bm-kicker">Central pessoal</p><h1 class="mt-2 font-display text-3xl font-black uppercase">Notificações</h1></header><div class="grid gap-3 lg:grid-cols-2"><article v-for="item in notices" :key="item.id" class="bm-panel rounded-md p-4"><span class="text-[10px] font-black uppercase tracking-[.16em] text-ember">{{ item.kind }}</span><h2 class="mt-2 font-display text-xl font-black">{{ item.title }}</h2><p class="mt-2 text-sm text-white/55">{{ item.summary || 'Novo aviso do servidor.' }}</p></article></div><p v-if="!notices.length" class="bm-panel rounded-md p-8 text-center text-sm text-white/45">Nenhuma notificação nova.</p></section></ManagementShell></template>
<script setup lang="ts">type Notice={id:string;title:string;summary?:string;kind:string}; const notices=ref<Notice[]>([]); const api=useContentApi(); onMounted(async()=>{try{const [news,events]=await Promise.all([api.entries<{data:Notice[]}>({kind:'NEWS',pageSize:10}),api.entries<{data:Notice[]}>({kind:'EVENT',pageSize:10})]);notices.value=[...news.data,...events.data]}catch{notices.value=[]}});useSeoMeta({title:'Notificações'})</script>
